//! A locale's catalogue: English source text in, that locale's text out.
//!
//! The React side sends every literal through Lingui's `_` macro, which reads
//! a `.po` file at startup. Here the catalogues are compiled in as sorted
//! `&[(msgid, text)]` tables (`src/catalog_data.rs`, generated by
//! `scripts/gen-catalog.mjs` from `src/locales/*.po`), so a lookup is a binary
//! search with no file IO and no initialisation order.
//!
//! The English text **is** the msgid, which is what makes the `t!` macro free
//! of key management — and what makes a missing translation harmless: it
//! resolves to the English source text.

use crate::SharedString;
use crate::catalog_data::table_for;
use crate::locale::Locale;

/// One locale's translations.
///
/// Cloning is cheap — a [`Locale`] plus a slice reference — so passing a
/// catalogue around costs no more than passing the locale.
#[derive(Clone, Debug)]
pub struct Catalog {
    locale: Locale,
    table: &'static [(&'static str, &'static str)],
}

impl Catalog {
    /// The source catalogue: no table, so every msgid resolves to itself.
    pub fn english() -> Self {
        Self { locale: Locale::english(), table: &[] }
    }

    /// The shipped catalogue for `locale`, or the English one when the
    /// language has no table.
    pub fn for_locale(locale: &Locale) -> Self {
        Self { locale: locale.clone(), table: table_for(locale.language()) }
    }

    /// A catalogue over an arbitrary table, for tests and future plugin
    /// catalogues.
    ///
    /// `table` must be sorted by `msgid`; [`Catalog`] binary searches it.
    /// Entries that are missing simply fall back to the msgid.
    pub fn new(locale: Locale, table: &'static [(&'static str, &'static str)]) -> Self {
        debug_assert!(
            table.windows(2).all(|pair| pair[0].0 <= pair[1].0),
            "catalogue tables must be sorted by msgid"
        );
        Self { locale, table }
    }

    /// The locale this catalogue translates into.
    pub fn locale(&self) -> &Locale {
        &self.locale
    }

    /// The underlying `(msgid, text)` pairs, sorted by msgid.
    pub fn table(&self) -> &'static [(&'static str, &'static str)] {
        self.table
    }

    /// How many translated messages this catalogue carries.
    pub fn len(&self) -> usize {
        self.table.len()
    }

    /// Whether this catalogue carries no translations at all.
    pub fn is_empty(&self) -> bool {
        self.table.is_empty()
    }

    /// Whether `msgid` has a translation here.
    pub fn has(&self, msgid: &str) -> bool {
        self.find(msgid).is_some()
    }

    /// The translation of `msgid`, or `msgid` itself when this locale has none.
    ///
    /// Both arms are `'static` — the table is compiled in and the msgid is a
    /// literal — so [`Catalog::get`] can build a [`SharedString`] without
    /// allocating.
    pub fn text(&self, msgid: &'static str) -> &'static str {
        self.find(msgid).unwrap_or(msgid)
    }

    /// [`Catalog::text`] as the [`SharedString`] widgets take.
    pub fn get(&self, msgid: &'static str) -> SharedString {
        SharedString::new_static(self.text(msgid))
    }

    fn find(&self, msgid: &str) -> Option<&'static str> {
        self.table
            .binary_search_by(|(key, _)| key.as_bytes().cmp(msgid.as_bytes()))
            .ok()
            .map(|index| self.table[index].1)
    }
}

impl Default for Catalog {
    fn default() -> Self {
        Self::english()
    }
}
